import {
  Activity,
  Clock,
  Dumbbell,
  Heart,
  ShieldCheck,
  UserCheck,
  Users,
  type LucideIcon,
} from "lucide-react";

// Optimized WebP files generated by `npm run images` from /Assets.
const files = import.meta.glob<string>("../assets/img/*.webp", { eager: true, import: "default" });
const file = (name: string) => files[`../assets/img/${name}.webp`];

export type Picture = { src: string; srcSet: string; alt: string };

function picture(name: string, sizes: [suffix: number, width: number][], alt: string): Picture {
  return {
    src: file(`${name}-${sizes[sizes.length - 1][0]}`),
    srcSet: sizes.map(([suffix, width]) => `${file(`${name}-${suffix}`)} ${width}w`).join(", "),
    alt,
  };
}

